```go
package main

import (
    "fmt"
    "sync"
)

func main() {
    var wg sync.WaitGroup
    values := make([]int, 3)

    for i := range values {
        wg.Add(1)
        go func(index int) {
            defer wg.Done()
            values[index] = (index + 1) * 10
        }(i)
    }

    wg.Wait()
    fmt.Println(values)
}
```
`Wait` returns only after all writes finish, so the output is always `[10 20 30]`. Each goroutine owns a different slice element, avoiding conflicting access.
